// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.securityimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.telemetry.AuditLogimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Play Integrity attestation. * * Verifies device integrity via Google Play Integrity API: *   - MEETS_DEVICE_INTEGRITY: app is running on a genuine Android device with *     Google Play services, and bootloader is locked. *   - MEETS_BASIC_INTEGRITY: app is running on a device that passes basic *     system integrity checks (may be rooted). *   - MEETS_STRONG_INTEGRITY: app is running on a device with recent security *     updates and strong hardware-backed protections. * * Strategy (per ADR 0007 — Soft Enforcement): *   - On launch, request standard integrity verdict *   - Cache result for 24 hours (don't spam API) *   - If verdict fails, gate sensitive features (Password Vault, voice biometrics, *     cloud LLM OAuth, bank SMS parsing, voice cloning) *   - Never hard-block — user is informed, not locked out * * The actual Play Integrity API call is made in :app (where the Play services * dependency lives). This class is the abstraction that other features use. */@Singletonclass IntegrityAttestation @Inject constructor(    private val auditLog: AuditLog,) {    private val _state = MutableStateFlow<IntegrityState>(IntegrityState.Unknown)    val state: StateFlow<IntegrityState> = _state.asStateFlow()    /**     * Update the cached integrity state. Called by :app after Play Integrity     * API call completes.     */    fun updateState(newState: IntegrityState, source: String) {        // CRITICAL FIX #56: Log integrity state changes for audit trail        if (_state.value::class.simpleName != newState::class.simpleName) {            Timber.tag("NOUS.Security").w("Integrity state CHANGED: ${_state.value::class.simpleName} → $newState (source: $source)")        } else {            Timber.tag("NOUS.Security").i("Integrity state → %s (source: %s)", newState, source)        }        _state.value = newState        auditLog.record(            type = AuditLog.EventType.INTEGRITY_CHECK,            action = "play_integrity_check",            outcome = when (newState) {                is IntegrityState.Valid -> AuditLog.AuditOutcome.SUCCESS                is IntegrityState.Compromised -> AuditLog.AuditOutcome.FAILURE                IntegrityState.Unknown -> AuditLog.AuditOutcome.ERROR            },            metadata = mapOf(                "state" to newState::class.simpleName.orEmpty(),                "source" to source,            ),        )    }    /**     * Convenience: is the device fully trustworthy for sensitive operations?     * False means caller should refuse and show a user-facing explanation.     */    fun isTrustworthy(): Boolean = _state.value is IntegrityState.Valid    /**     * Convenience: is the device rooted? Caller can decide whether to allow     * power-user features (hacker module) but block financial features.     */    fun isRooted(): Boolean = _state.value is IntegrityState.Compromised}/** Integrity verdict. */sealed interface IntegrityState {    /** Verdict not yet obtained (first launch, network failure, etc.) */    data object Unknown : IntegrityState    /** Device passes integrity checks (MEETS_DEVICE_INTEGRITY or stronger). */    data class Valid(        val verdict: Verdict,        val checkedAtEpochMs: Long = 0L,    ) : IntegrityState {        enum class Verdict { BASIC, DEVICE, STRONG }    }    /** Device fails integrity checks (rooted, unlocked bootloader, tampered). */    data class Compromised(        val reason: String,        val signals: List<String> = emptyList(),    ) : IntegrityState}